SINA_SMART["anat2-liver"] = {"lecture":"anat2-liver","title":"The liver","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-liver:e0","text":"Largest abdominal organ; ~2% of adult weight.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e1","text":"Double inflow (portal vein, hepatic artery), double outflow (hepatic veins, bile ducts).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e2","text":"Mostly right hypochondrium; upper border 5th right rib to 6th left rib.","topic":"Location, surfaces and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e3","text":"Surfaces: diaphragmatic, visceral, posterior (bare area, IVC groove).","topic":"Location, surfaces and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e4","text":"Ligaments: falciform, round (umbilical vein), coronary, triangular, lesser omentum, ligamentum venosum (ductus venosus).","topic":"Ligaments, lobes and porta hepatis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e5","text":"Lobes: right, left, quadrate, caudate.","topic":"Ligaments, lobes and porta hepatis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e6","text":"Hepatoduodenal ligament: portal triad; Pringle manoeuvre.","topic":"Ligaments, lobes and porta hepatis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e7","text":"Portosystemic anastomoses: oesophageal, paraumbilical, rectal, retroperitoneal.","topic":"Ligaments, lobes and porta hepatis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e9","text":"Segment 1 = caudate lobe.","topic":"Ligaments, lobes and porta hepatis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e10","text":"Nerves: hepatic plexus; intercostals to Glisson's capsule.","topic":"Functional anatomy, nerves and lymph","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-liver:e8","text":"Couinaud: 2 hemilivers, 4 sectors, 8 segments; middle hepatic vein divides halves.","topic":"Functional anatomy, nerves and lymph","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"jo15jk":"a","1q5mb3f":"a","10494uz":"a","dquf3o":"a","145n8hw":"a","1utir52":"a","1s3lutv":"a","147qpg7":"a","1763dok":"a","my7otq":"a","3vsmt4":"a","lwrdmb":"a","1x4hafx":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-liver:e0":{"s":0,"u":["Largest abdominal organ; ~2% of adult weight.","The liver is the largest abdominal organ (about 2% of adult body weight, 4-5% in infants), wedge-shaped and reddish brown, a vital organ for homeostasis, nutrition and defence (detoxification, protein synthesis, bile production, glycogen storage)."],"dp":[]},"anat2-liver:e1":{"s":0,"u":["Double inflow (portal vein, hepatic artery), double outflow (hepatic veins, bile ducts).","Its 'hidden' anatomy has a double inflow (portal vein and hepatic artery) and a double outflow (hepatic veins and bile ducts)."],"dp":[{"h":"Note","t":"Double inflow (portal vein ~75%, hepatic artery ~25%) and double outflow (hepatic veins → IVC; bile ducts)."}]},"anat2-liver:e2":{"s":1,"u":["Mostly right hypochondrium; upper border 5th right rib to 6th left rib.","Surface markings (neutral breathing): superior border from the 5th right rib to the 6th left rib via the xiphisternal junction; inferior border from the 10th right costal cartilage to the 6th left rib (may be palpable in healthy adults); it moves with breathing (risk of pneumothorax during liver puncture).","It lies mostly in the right hypochondrium (about three quarters) and extends into the epigastrium and left hypochondrium."],"dp":[]},"anat2-liver:e3":{"s":1,"u":["Surfaces: diaphragmatic, visceral, posterior (bare area, IVC groove).","Surfaces: diaphragmatic (under the domes; above lie the right lung and heart); visceral/inferior (gallbladder, porta hepatis, lesser omentum; impressions of oesophagus, stomach, duodenum, right colic flexure, right kidney and adrenal); posterior with the bare area (not covered by peritoneum, bounded by the coronary ligaments) and the groove of the inferior vena cava ."],"dp":[{"h":"Note","t":"Bare area (between the coronary ligament layers) touches the diaphragm directly. Hepatorenal pouch (Morison's) is the lowest part of the upper abdominal cavity when lying supine: fluid collects there."}]},"anat2-liver:e4":{"s":2,"u":["Ligaments: falciform, round (umbilical vein), coronary, triangular, lesser omentum, ligamentum venosum (ductus venosus).","Six peritoneal 'ligaments': falciform (to the anterior wall), round ligament (ligamentum teres) , remnant of the umbilical vein , coronary and right and left triangular ligaments (to the diaphragm), the lesser omentum (to the lesser curvature), and the ligamentum venosum , remnant of the ductus venosus .","Anatomical lobes (external appearance): right , left (divided by the falciform ligament), quadrate (between gallbladder and ligamentum teres, part of the right lobe) and caudate (between IVC and ligamentum venosum)."],"dp":[{"h":"Note","t":"Ligament remnants : ligamentum teres = umbilical vein; ligamentum venosum = ductus venosus. The falciform ligament carries the teres in its free edge."}]},"anat2-liver:e5":{"s":2,"u":["Lobes: right, left, quadrate, caudate.","Anatomical lobes (external appearance): right , left (divided by the falciform ligament), quadrate (between gallbladder and ligamentum teres, part of the right lobe) and caudate (between IVC and ligamentum venosum)."],"dp":[]},"anat2-liver:e6":{"s":2,"u":["Hepatoduodenal ligament: portal triad; Pringle manoeuvre.","The hepatoduodenal ligament carries the portal triad (portal vein, hepatic artery, bile duct) to the porta hepatis (hilum); behind it lies the omental foramen ; clamping it ( Pringle manoeuvre ) stops liver inflow."],"dp":[{"h":"Clinical","t":"Pringle manoeuvre (clamping the hepatoduodenal ligament) stops portal and arterial inflow; bleeding that continues comes from the hepatic veins/IVC . Liver biopsy in the right mid-axillary line risks pneumothorax."}]},"anat2-liver:e7":{"s":2,"u":["Portosystemic anastomoses: oesophageal, paraumbilical, rectal, retroperitoneal.","Portosystemic anastomoses : oesophageal , paraumbilical (caput medusae), rectal and retroperitoneal ; in portal hypertension they dilate and varices can bleed."],"dp":[{"h":"Memory aid","t":"Portosystemic anastomoses : oesophageal (varices), paraumbilical (caput medusae), rectal (anorectal varices), retroperitoneal ."}]},"anat2-liver:e9":{"s":2,"u":["Segment 1 = caudate lobe.","Anatomical lobes (external appearance): right , left (divided by the falciform ligament), quadrate (between gallbladder and ligamentum teres, part of the right lobe) and caudate (between IVC and ligamentum venosum)."],"dp":[{"h":"Why surgeons use segments, not lobes","t":"The four anatomical lobes are defined by surface features and do not match the internal blood supply: the quadrate lobe, for example, is fed by the left portal pedicle. Couinaud's eight segments each have their own portal, arterial and biliary pedicle and are separated by the hepatic veins, so a surgeon can remove one or more segments while leaving the rest fully supplied and drained. Source: the lecture's functional division slides."},{"h":"Note","t":"Caudate lobe (between IVC and ligamentum venosum) = segment 1 , drains directly into the IVC. Quadrate lobe (between gallbladder and teres) is part of the functional left liver (segment 4)."}]},"anat2-liver:e10":{"s":3,"u":["Nerves: hepatic plexus; intercostals to Glisson's capsule.","Nerves : hepatic plexus with sympathetic fibres (coeliac and superior mesenteric plexuses) and parasympathetic fibres (vagal trunks); lower intercostal nerves supply Glisson's capsule ."],"dp":[{"h":"Clinical","t":"Glisson's capsule pain is carried by lower intercostal and phrenic fibres → right upper quadrant and right shoulder pain."}]},"anat2-liver:e8":{"s":3,"u":["Couinaud: 2 hemilivers, 4 sectors, 8 segments; middle hepatic vein divides halves.","The functional (Couinaud) division , based on independent inflow, drainage and bile outflow, is used in surgery: 2 hemilivers (separated by the main portal fissure, plane of the middle hepatic vein ), 4 sectors and 8 segments (1 = caudate; 2-4 left; 5-8 right), each with its own Glissonian pedicle.","The three hepatic veins (right, middle, left) join the IVC at the hepatocaval confluence."],"dp":[{"h":"Note","t":"Anatomical vs functional : anatomically the falciform ligament divides right and left lobes; functionally the dividing plane is the middle hepatic vein (Cantlie's line, gallbladder to IVC). Couinaud: 8 segments."}]}},"meta":{"jo15jk":{"a":"recall","vg":"anat2-liver:e0/recall/1"},"1q5mb3f":{"a":"recall","vg":"anat2-liver:e1/recall/1"},"10494uz":{"a":"recall","vg":"anat2-liver:e2/recall/1"},"dquf3o":{"a":"recall","vg":"anat2-liver:e3/recall/1"},"145n8hw":{"a":"recall","vg":"anat2-liver:e4/recall/1"},"1utir52":{"a":"relationship","vg":"anat2-liver:e9/relationship/1"},"1s3lutv":{"a":"recall","vg":"anat2-liver:e6/recall/1"},"147qpg7":{"a":"recall","vg":"anat2-liver:e7/recall/1"},"1763dok":{"a":"recall","vg":"anat2-liver:e7/recall/1"},"my7otq":{"a":"recall","vg":"anat2-liver:e8/recall/1"},"3vsmt4":{"a":"recall","vg":"anat2-liver:e8/recall/2"},"lwrdmb":{"a":"recall","vg":"anat2-liver:e9/recall/1"},"1x4hafx":{"a":"recall","vg":"anat2-liver:e10/recall/1"}},"explRev":"34189a5d3840"};
